#!/usr/bin/env bash
# PostToolUse hook (matcher: the GitHub MCP tools that publish a PR description, a comment
# or a review). In Claude Code cloud sessions the GitHub MCP server can append a
# "Generated by Claude Code" footer with a Claude session link to the published text,
# server-side, even when the text Claude sent had none; settings.json `attribution` cannot
# prevent it. This hook cannot edit GitHub itself (hooks have no access to MCP tools), so it
# reminds Claude, through additionalContext, to read the text back and remove the footer,
# as rules/git-commits.md asks.
#
# Input (JSON on stdin) is ignored. Always prints the same JSON and exits 0.
# Bash 3.2 compatible, no jq.

cat >/dev/null 2>&1

# Literal JSON: keep it valid when editing the message (double quotes escaped as \").
cat <<'JSON'
{"hookSpecificOutput":{"hookEventName":"PostToolUse","additionalContext":"The GitHub tool may have appended a \"Generated by Claude Code\" footer or a Claude session link to the text you just published. Read it back now, remove any such line (and the \"---\" line before it), then read it back again to confirm it is gone, per rules/git-commits.md."}}
JSON
exit 0
